(()=>{'use strict';const root=document.querySelector('#dashboard');let session={},data={},tab='overview',dirty=false,editing=null,search='',filter='all',trash=false;const titles={overview:'Overview',tours:'Experiences',locations:'Destinations',posts:'Travel journal',pages:'Website pages',bookings:'Paid bookings',inquiries:'Enquiries',settings:'Brand & contact',payments:'Stripe payments',email:'Email delivery',security:'Account security',reviews:'Guest reviews',users:'Users',tracking:'Tracking & verification'};const symbols=Object.fromEntries(Object.keys(titles).map(k=>[k,studioIcon(k)]));const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>'AED '+Number(n||0).toLocaleString('en-AE',{maximumFractionDigits:2});const live=r=>!r.deletedAt&&r.status==='published'&&(!r.publishedAt||r.publishedAt.slice(0,10)<=new Date().toISOString().slice(0,10));const publicPath=(p,kind)=>p.systemPath||'/'+(kind==='posts'?'guides/':kind==='locations'?'destinations/':kind==='pages'?'':'tours/')+p.slug;const badge=(text,type='')=>`<span class="badge ${type}">${e(text)}</span>`;function toast(msg,error=false){const t=document.querySelector('#toast');t.textContent=msg;t.className='visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',6000)}async function api(path,body){const r=await fetch('/api/'+path,body===undefined?{headers:{Accept:'application/json'}}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:JSON.stringify(body)});let d;try{d=await r.json()}catch{throw Error('The server could not complete this request. Please try again.')}if(!r.ok){if(r.status===401){session.admin=false;login()}throw Error(d.error||'Please try again.')}return d}function input(label,name,value='',type='text',hint='',attrs=''){return `<label>${label}<input type="${type}" name="${e(name)}" value="${e(value)}" ${attrs}>${hint?`<span class="hint">${hint}</span>`:''}</label>`}function area(label,name,value='',rows=3,hint=''){return `<label>${label}<textarea name="${e(name)}" rows="${rows}">${e(value)}</textarea>${hint?`<span class="hint">${hint}</span>`:''}</label>`}function select(label,name,value,options){return `<label>${label}<select name="${e(name)}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(t)}</option>`}).join('')}</select></label>`}function check(label,name,checked=false,hint=''){return `<label class="check"><input type="checkbox" name="${e(name)}" ${checked?'checked':''}><span><strong>${label}</strong>${hint?`<small>${hint}</small>`:''}</span></label>`}function head(title,desc,actions=''){return `<div class="page-title"><div><h1>${e(title)}</h1><p>${e(desc)}</p></div><div class="page-actions">${actions}</div></div>`}function btn(text,action,kind='secondary',attrs=''){return `<button class="button ${kind}" type="button" ${action} ${attrs}>${text}</button>`}function empty(title,desc){return `<div class="empty-state"><h2>${e(title)}</h2><p>${e(desc)}</p></div>`}function viewLink(p,kind){return `<a class="button secondary small" href="${e(publicPath(p,kind))}" target="_blank" rel="noopener noreferrer">View ↗</a>`}function contentDirty(){dirty=true}async function reload(){data=await api('admin')}function go(next){if(dirty&&!confirm('You have unsaved changes. Leave without saving?'))return;dirty=false;editing=null;search='';filter='all';trash=false;tab=next;location.hash=next;render()}function shell(content){root.innerHTML=`<div class="studio"><aside class="sidebar"><a class="sidebar-brand" href="/" target="_blank" rel="noopener noreferrer"><img src="${e(data.settings?.logo||'/assets/logo.webp')}" alt="Desert Sky Tourism logo"><strong>Desert Sky<span>Studio</span></strong></a><nav aria-label="Dashboard navigation"><div class="nav-label">Your workspace</div>${['overview','tours','locations','posts','reviews','pages','bookings','inquiries','users'].map(t=>`<button data-nav="${t}" class="${tab===t?'active':''}" ${tab===t?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${symbols[t]}</span>${titles[t]}${['tours','locations','posts'].includes(t)?`<span class="item-count">${data[t].filter(live).length}</span>`:''}</button>`).join('')}<div class="nav-label">Settings</div>${['settings','tracking','payments','email','security'].map(t=>`<button data-nav="${t}" class="${tab===t?'active':''}"><span class="nav-icon" aria-hidden="true">${symbols[t]}</span>${titles[t]}</button>`).join('')}</nav><div class="sidebar-bottom">Signed in as<strong>${e(session.email)}</strong><p style="margin-top:15px">Desert Sky Tourism<br>desertskytourism.com</p></div></aside><div class="workspace"><header class="studio-top"><button class="mobile-sidebar" aria-label="Toggle dashboard menu">☰</button><div class="studio-breadcrumb"><span>Workspace</span><span>/</span><strong>${e(titles[tab])}</strong></div><div class="top-actions"><button class="studio-search-button" type="button" data-studio-search aria-label="Search your workspace">${studioIcon('search')}<span>Search your workspace</span><kbd>⌘ K</kbd></button><span class="environment">Live website</span><a href="/" target="_blank" rel="noopener noreferrer" class="button secondary small">View website ↗</a><span class="studio-avatar" aria-label="Administrator account">${e(session.email?.slice(0,1).toUpperCase()||'D')}</span><button class="button secondary small" data-logout>Sign out</button></div></header><main class="main-content">${content}</main></div></div>`;root.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));root.querySelector('[data-logout]').onclick=async()=>{if(dirty&&!confirm('Leave without saving your changes?'))return;await api('logout',{});dirty=false;session.admin=false;login()};root.querySelector('.mobile-sidebar').onclick=()=>root.querySelector('.sidebar').classList.toggle('open');bindCommon();root.querySelector('[data-studio-search]').onclick=openStudioSearch;}function bindCommon(){root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));root.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>edit());root.querySelectorAll('[data-booking]').forEach(b=>b.onclick=()=>booking(b.dataset.booking));root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteItem(b.dataset.delete));root.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>restoreItem(b.dataset.restore));root.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>go(tab));root.querySelectorAll('[data-refresh]').forEach(b=>b.onclick=async()=>{await reload();render();toast('Dashboard refreshed.')});root.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>go(b.dataset.quick))}function render(){dirty=false;if(['tours','locations','posts','pages'].includes(tab))list();else if(tab==='users')users();else if(tab==='reviews')reviews();else if(tab==='overview')overview();else if(tab==='bookings')bookings();else if(tab==='inquiries')inquiries();else if(tab==='settings')settings();else if(tab==='tracking')tracking();else if(tab==='payments')payments();else if(tab==='email')email();else security()}
function overview(){const bookings=data.bookings.filter(b=>!b.deletedAt),paid=bookings.filter(b=>b.mode==='live'),pending=bookings.filter(b=>b.status==='pending'),tourCount=data.tours.filter(live).length;const metrics=[['tours','Live experiences',tourCount,'Ready for the next adventure'],['locations','Destinations',data.locations.filter(live).length,'Places with a new perspective'],['bookings','Paid bookings',bookings.length,pending.length+' awaiting tour confirmation'],['payments','Live revenue',money(paid.reduce((s,b)=>s+b.total,0)),'Gross payments before fees & refunds']];shell(head('A new day. New possibilities.','Welcome to Desert Sky Studio. Let’s make the next adventure happen.',btn('+ Create an experience','data-overview-new',''))+`<section class="studio-welcome"><div><span class="studio-eyebrow">YOUR TRAVEL BUSINESS, BEAUTIFULLY CONNECTED</span><h2>A little inspiration.<br>A world of opportunity.</h2><p>Your experiences, stories and guest journeys — all in one thoughtful workspace.</p><a href="/" target="_blank" rel="noopener noreferrer" class="button">Explore your website ${studioIcon('arrow')}</a></div><div class="welcome-orbit">${studioIcon('locations')}<span>A new sky.<br>A new life.</span></div></section><div class="metrics">${metrics.map(([i,l,v,c],idx)=>`<article class="metric metric-${idx}"><div class="metric-top"><span class="metric-icon">${studioIcon(i)}</span><span>${e(l)}</span></div><strong>${e(v)}</strong><small>${e(c)}</small></article>`).join('')}</div><div class="studio-overview-columns"><section class="panel"><div class="panel-head"><div><span class="studio-eyebrow">DESTINATION MIX</span><h2>A world of experiences.</h2></div>${btn('Manage','data-quick="locations"','secondary small')}</div><div class="destination-coverage">${data.locations.filter(live).map(l=>{const n=data.tours.filter(t=>live(t)&&t.location===l.id).length;return `<div class="coverage-row"><img src="${e(l.image)}" alt=""><div><div><strong>${e(l.title)}</strong><span>${n} experiences</span></div><div class="coverage-bar"><span style="width:${Math.round(n/Math.max(1,tourCount)*100)}%"></span></div></div></div>`}).join('')}</div></section><section class="panel launch-panel"><div class="panel-head"><div><span class="studio-eyebrow">YOUR LAUNCH ESSENTIALS</span><h2>Ready for great days?</h2></div></div><div class="launch-item"><span class="launch-icon ${data.stripe.enabled?'ready':''}">${studioIcon('payments')}</span><div><strong>Secure tour payments</strong><small>${data.stripe.enabled?'Stripe checkout is connected.':'Connect your Stripe test key to enable checkout.'}</small></div>${btn(data.stripe.enabled?'Manage':'Connect','data-quick="payments"','secondary small')}</div><div class="launch-item"><span class="launch-icon ${data.mail.configured?'ready':''}">${studioIcon('email')}</span><div><strong>Keep guests in the loop</strong><small>${data.mail.configured?'Your sending mailbox is configured.':'Connect SMTP for receipts and status emails.'}</small></div>${btn('Set up','data-quick="email"','secondary small')}</div><div class="launch-item"><span class="launch-icon">${studioIcon('reviews')}</span><div><strong>Stories worth sharing</strong><small>${(data.reviews||[]).filter(r=>!r.deletedAt&&!r.isSample).length} genuine reviews in your library.</small></div>${btn('Edit','data-quick="reviews"','secondary small')}</div><p class="studio-note">${data.tours.filter(t=>live(t)&&!Number(t.discountPrice||t.price)).length} experiences are enquiry-only until you add a current price. Published pages are available to search engines unless individually hidden.</p></section></div><div class="panel studio-bookings-panel"><div class="panel-head"><div><span class="studio-eyebrow">THE JOURNEYS AHEAD</span><h2>Recent paid bookings</h2></div>${btn('View all bookings','data-quick="bookings"','secondary small')}</div>${bookingTable(bookings.slice().sort((a,b)=>b.paidAt.localeCompare(a.paidAt)).slice(0,5))}</div>`);root.querySelector('[data-overview-new]').onclick=()=>{tab='tours';location.hash='tours';edit()};}
function list(){
 const singular={tours:'experience',posts:'article',locations:'destination',pages:'page'}[tab];
 const selected=data[tab].filter(p=>trash?!!p.deletedAt:!p.deletedAt).filter(p=>(!search||[p.title,p.slug,p.summary].join(' ').toLowerCase().includes(search.toLowerCase()))&&(filter==='all'||p.status===filter));
 const desc={tours:'Manage tour details, prices, extras and SEO. Move old tours to Trash and restore them any time.',posts:'Write useful travel stories with a classic editor, publication dates and search previews.',locations:'Three destinations to start. Add another location and assign experiences whenever you need.',pages:'Edit website information and SEO. Core pages keep their reserved URLs.'}[tab];
 const rows=selected.map(p=>{
  const price=Number(p.discountPrice||p.price)>0?money(p.discountPrice||p.price):'<span class="muted">Enquiry only</span>';
  const tourCells=tab==='tours'?`<td>${e(data.locations.find(l=>l.id===p.location)?.title||p.location)}</td><td>${price}</td>`:'';
  const actions=trash?btn('Restore',`data-restore="${e(p.id)}"`,'secondary small'):btn('Edit',`data-edit="${e(p.id)}"`,'secondary small')+viewLink(p,tab)+(p.systemPath?'':btn('Trash',`data-delete="${e(p.id)}"`,'danger small'));
  return `<tr><td><div class="table-title"><img src="${e(p.image)}" alt="" loading="lazy"><div><strong>${e(p.title)}</strong><small>${e(publicPath(p,tab))}</small></div></div></td>${tourCells}<td>${badge(trash?'In Trash':p.status,p.status==='published'&&!trash?'green':trash?'red':'orange')}</td><td><small>${e((p.updatedAt||p.publishedAt||'').slice(0,10))}</small></td><td><div class="table-actions">${actions}</div></td></tr>`;
 }).join('');
 const table=selected.length?`<div class="table-wrap"><table><thead><tr><th>${titles[tab]}</th>${tab==='tours'?'<th>Destination</th><th>Price</th>':''}<th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty(trash?'Nothing in Trash.':'No results yet.',trash?'Deleted content can be restored here.':'Add new content or try a different search.');
 shell(head(titles[tab],desc,btn(trash?'Back to active':'Show Trash','data-trash')+btn('+ Add '+singular,'data-new',''))+`<div class="filters"><input id="content-search" type="search" placeholder="Search ${e(titles[tab].toLowerCase())}…" aria-label="Search content" value="${e(search)}"><select id="content-status" aria-label="Filter publication status"><option value="all" ${filter==='all'?'selected':''}>All statuses</option><option value="published" ${filter==='published'?'selected':''}>Published</option><option value="draft" ${filter==='draft'?'selected':''}>Draft</option></select><span class="count-label">${selected.length} ${singular}${selected.length!==1?'s':''}${trash?' in Trash':''}</span></div>`+table);
 root.querySelector('[data-trash]').onclick=()=>{trash=!trash;search='';list()};
 const f=root.querySelector('#content-search');f.oninput=()=>{const pos=f.selectionStart;search=f.value;list();const next=root.querySelector('#content-search');next.focus();next.setSelectionRange(pos,pos)};
 root.querySelector('#content-status').onchange=ev=>{filter=ev.target.value;list()};
}
async function deleteItem(id){const p=data[tab].find(p=>p.id===id);if(!p)return;if(!confirm(`Move “${p.title}” to Trash? It will be removed from the public website. You can restore it from the dashboard.`))return;try{await api('content',{kind:tab,action:'delete',id});await reload();editing=null;dirty=false;if(tab==='reviews')reviews();else list();toast('Moved to Trash. You can restore it any time.')}catch(err){toast(err.message,true)}}async function restoreItem(id){try{await api('content',{kind:tab,action:'restore',id});await reload();if(tab==='reviews')reviews();else list();toast('Content restored.')}catch(err){toast(err.message,true)}}
function rich(content){return `<div class="editor-label">Content</div><div class="rich-toolbar"><select data-format aria-label="Paragraph style"><option value="p">Paragraph</option><option value="h2">Heading 2</option><option value="h3">Heading 3</option><option value="h4">Heading 4</option></select><button type="button" data-command="bold" aria-label="Bold"><b>B</b></button><button type="button" data-command="italic" aria-label="Italic"><i>I</i></button><button type="button" data-command="insertUnorderedList" aria-label="Bullet list">• List</button><button type="button" data-command="insertOrderedList" aria-label="Numbered list">1. List</button><button type="button" data-link>Link</button><button type="button" data-command="unlink">Unlink</button><button type="button" data-command="removeFormat">Clear</button><button type="button" data-source>HTML</button></div><div id="rich-content" class="rich-editor" contenteditable="true" role="textbox" aria-label="Page content" aria-multiline="true">${content||'<p></p>'}</div><textarea id="source-content" class="source-area" aria-label="HTML content" hidden></textarea><span class="hint">Use headings, links and lists to organise your content. Paste plain text to avoid unwanted formatting. Scripts and embeds are removed when saved.</span>`}
function imageFields(p,name='image',label='Featured image'){return `<h3>${label}</h3><img class="image-preview" data-image-preview="${name}" src="${e(p[name]||'/assets/dubai.webp')}" alt="Selected image preview">${input('Image URL',name,p[name]||'','text','Use an uploaded image or existing asset path.')}<div class="upload-button"><input type="file" accept="image/jpeg,image/png,image/webp" data-upload="${name}" aria-label="Upload ${label.toLowerCase()}"></div>${name==='image'?input('Image alt text','imageAlt',p.imageAlt||p.title||'','text','Describe what the image shows.'):''}`}
function addonRow(a={}){return `<div class="addon-row" data-addon="${e(a.id||crypto.randomUUID().replaceAll('-','').slice(0,16))}">${input('Add-on name','addonTitle',a.title||'')}${input('Price (AED)','addonPrice',a.price??0,'number','','min="0" step="0.01"')}${select('Charge by','addonMode',a.mode||'per_unit',[['per_unit','Per unit'],['per_person','Per person']])}${btn('Remove','data-remove-addon','danger small')}</div>`}
function seoPanel(p){return `<div class="panel"><h3>Search engine optimisation</h3>${input('SEO title','seoTitle',p.seo?.title||'','text','Aim for a clear, distinctive title.')}<span class="hint" id="title-count"></span>${area('Meta description','seoDescription',p.seo?.description||'',4,'A complete summary, usually around 140–160 characters.')}<span class="hint" id="description-count"></span>${area('Target keywords','seoKeywords',p.seo?.keywords||'',3,'Editorial targets. Meta keywords alone do not determine Google rankings.')}${check('Hide from search engines','noindex',p.seo?.noindex,'Keep this page out of the sitemap. Hidden pages are excluded from the sitemap.')}<div class="seo-preview"><small>desertskytourism.com</small><strong id="seo-preview-title">${e(p.seo?.title||p.title)}</strong><p id="seo-preview-description">${e(p.seo?.description||p.summary)}</p></div></div>`}
function edit(id){if(tab==='reviews'){editReview(id);return}editing=data[tab].find(p=>p.id===id)||{id:'',title:'',slug:'',summary:'',content:'',image:'/assets/dubai.webp',imageAlt:'',status:'draft',publishedAt:new Date().toISOString().slice(0,10),location:data.locations.find(live)?.id||'',price:'',discountPrice:'',pricingMode:'per_person',capacity:7,ticketOptions:1,addons:[],highlights:[]};const p=editing;const kind=tab;const title=kind==='tours'?'experience':kind==='posts'?'article':kind==='locations'?'destination':'page';shell(head(p.id?'Edit '+title:'Create a new '+title,'A thoughtful title, useful details and a clear next step.',btn('← Back to list','data-back')+(p.id?viewLink(p,kind):''))+`<form id="content-form"><div class="edit-grid"><div><div class="panel">${input('Title','title',p.title,'text','','required maxlength="200"')}${input('URL slug','slug',p.slug,'text','Use clear, lowercase words separated by hyphens.',p.systemPath?'readonly':'required')}<span class="url-preview" id="url-preview">${e(location.origin+publicPath(p,kind))}</span>${area('Short description','summary',p.summary,3,'Used on cards and introductions. Keep it specific and useful.')}${rich(p.content)}</div>${kind==='tours'?`<div class="panel"><h2>Experience & pricing</h2><div class="two">${select('Destination','location',p.location,data.locations.filter(live).map(l=>[l.id,l.title]))}${input('Experience category','category',p.category||'Experiences','text','For example: Desert adventures or City & culture.')}</div><div class="two">${input('Duration','duration',p.duration||'','text','For example: 4 hours or 1 hour.')}${select('Price basis','pricingMode',p.pricingMode,[['per_person','Per person'],['per_group','Per vehicle / group'],['per_hour','Per hour']])}</div><div class="three">${input('Regular price (AED)','price',p.price,'number','Use 0 for enquiry-only.','min="0" max="100000" step="0.01"')}${input('Discounted price (AED)','discountPrice',p.discountPrice,'number','Optional; must be lower than the regular price.','min="0" step="0.01"')}${input('Capacity per vehicle / yacht','capacity',p.capacity,'number','','min="1" max="100"')}</div>${input('Ticket options shown on card','ticketOptions',p.ticketOptions,'number','Number of available ticket options, not a live stock limit.','min="1" max="100"')}${check('Feature on the homepage','featured',p.featured)}</div><div class="panel"><h2>A closer look — photo gallery</h2><p class="hint">Add relevant photographs for the tour detail gallery. Your featured image is always shown first.</p>${area('Gallery image URLs — one per line','galleryImages',(p.gallery||[]).join('\n'),4)}<label class="gallery-upload-label">Upload gallery photographs<input type="file" data-gallery-upload multiple accept="image/jpeg,image/png,image/webp"></label></div><div class="panel"><h2>Tour details</h2>${area('Highlights — one per line','highlights',(p.highlights||[]).join('\n'),5)}${area('What’s included','inclusions',p.inclusions||'',4)}${area('Not included','exclusions',p.exclusions||'',4)}${area('Pickup / meeting point','pickup',p.pickup||'',3,'State included areas, meeting point and any extra transfer fees.')} ${area('Cancellation & refund conditions','cancellation',p.cancellation||'',4,'Set the conditions before accepting live payments.')}</div><div class="panel"><div class="panel-head"><h2>Optional add-ons</h2>${btn('+ Add an extra','data-add-addon','secondary small')}</div><p class="hint">Per-person extras apply to all guests. Per-unit extras use the quantity selected at checkout.</p><div id="addon-list">${(p.addons||[]).map(addonRow).join('')}</div></div>`:''}</div><aside class="edit-aside"><div class="panel"><h3>Publish</h3>${select('Status','status',p.status,[['draft','Draft'],['published','Published']])}${input('Publication date','publishedAt',p.publishedAt?.slice(0,10)||'','date','Shown on journal articles. Future dates stay hidden until that date.')}<p class="hint">${p.updatedAt?'Last saved '+e(new Date(p.updatedAt).toLocaleString()):'Not yet published.'}</p></div><div class="panel">${imageFields(p)}</div>${seoPanel(p)}</aside></div><div class="save-bar">${p.id&&!p.systemPath?btn('Move to Trash',`data-delete="${e(p.id)}"`,'danger'):''}<button class="button" type="submit">Save ${title}</button></div><div class="form-error" role="alert"></div></form>`);const form=root.querySelector('#content-form');if(!p.id){let customSlug=false;form.elements.slug.addEventListener('input',()=>customSlug=true);form.elements.title.addEventListener('input',()=>{if(!customSlug)form.elements.slug.value=form.elements.title.value.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')})}form.addEventListener('input',contentDirty);form.addEventListener('change',contentDirty);bindRich();bindUploads();bindGalleryUploads();bindAddon();root.querySelector('[data-add-addon]')?.addEventListener('click',()=>{root.querySelector('#addon-list').insertAdjacentHTML('beforeend',addonRow());bindAddon();dirty=true});const updatePreview=()=>{const f=new FormData(form);root.querySelector('#title-count').textContent=String(f.get('seoTitle')||'').length+' characters';root.querySelector('#description-count').textContent=String(f.get('seoDescription')||'').length+' characters';root.querySelector('#seo-preview-title').textContent=f.get('seoTitle')||f.get('title');root.querySelector('#seo-preview-description').textContent=f.get('seoDescription')||f.get('summary');root.querySelector('#url-preview').textContent=location.origin+(p.systemPath||publicPath({slug:f.get('slug')},kind))};form.addEventListener('input',updatePreview);updatePreview();form.onsubmit=async ev=>{ev.preventDefault();const values=Object.fromEntries(new FormData(form));values.id=p.id;values.content=root.querySelector('#source-content').hidden?root.querySelector('#rich-content').innerHTML:root.querySelector('#source-content').value;values.seo={title:values.seoTitle,description:values.seoDescription,keywords:values.seoKeywords,noindex:!!values.noindex};values.featured=!!values.featured;values.gallery=String(values.galleryImages||'').split('\n').map(x=>x.trim()).filter(Boolean);values.addons=Array.from(root.querySelectorAll('[data-addon]')).map(r=>({id:r.dataset.addon,title:r.querySelector('[name=addonTitle]').value,price:Number(r.querySelector('[name=addonPrice]').value),mode:r.querySelector('[name=addonMode]').value}));const b=form.querySelector('[type=submit]');b.disabled=true;try{const r=await api('content',{kind,value:values});await reload();dirty=false;edit(r.value.id);toast('Saved. Your website content is updated.')}catch(err){form.querySelector('.form-error').textContent=err.message;toast(err.message,true);b.disabled=false}};dirty=false}
function sanitiseEditorHTML(html){const tpl=document.createElement('template');tpl.innerHTML=html;const allowed=new Set(['P','H2','H3','H4','STRONG','B','EM','I','UL','OL','LI','A','BR','BLOCKQUOTE','HR','TABLE','TR','TH','TD','TBODY','THEAD']);for(const el of Array.from(tpl.content.querySelectorAll('*'))){if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','FORM','IMG','NOSCRIPT'].includes(el.tagName)){el.remove();continue}const href=el.getAttribute('href');for(const attr of Array.from(el.attributes))el.removeAttribute(attr.name);if(el.tagName==='A'&&href&&/^(https:\/\/|\/[^/]|mailto:|tel:|#)/.test(href))el.setAttribute('href',href);if(!allowed.has(el.tagName))el.replaceWith(...el.childNodes);}return tpl.innerHTML;}
function bindRich(){const editor=root.querySelector('#rich-content'),source=root.querySelector('#source-content');root.querySelectorAll('[data-command]').forEach(b=>{b.onmousedown=ev=>ev.preventDefault();b.onclick=()=>{editor.focus();document.execCommand(b.dataset.command,false,null);dirty=true}});root.querySelector('[data-format]').onchange=ev=>{editor.focus();document.execCommand('formatBlock',false,ev.target.value);dirty=true};root.querySelector('[data-link]').onmousedown=ev=>ev.preventDefault();root.querySelector('[data-link]').onclick=()=>{const url=prompt('Enter a website URL (https://…), a local page path (/tours/…), or a mailto: / tel: link.');if(url&&/^(https:\/\/|\/[^/]|mailto:|tel:|#)/.test(url)){editor.focus();document.execCommand('createLink',false,url);dirty=true}else if(url)toast('Please enter a valid website or local link.',true)};root.querySelector('[data-source]').onclick=()=>{if(source.hidden){source.value=editor.innerHTML;source.hidden=false;editor.hidden=true}else{editor.innerHTML=sanitiseEditorHTML(source.value);source.hidden=true;editor.hidden=false}dirty=true};editor.addEventListener('paste',ev=>{ev.preventDefault();document.execCommand('insertText',false,ev.clipboardData.getData('text/plain'));dirty=true})}function bindAddon(){root.querySelectorAll('[data-remove-addon]').forEach(b=>b.onclick=()=>{b.closest('[data-addon]').remove();dirty=true})}function bindUploads(){root.querySelectorAll('[data-upload]').forEach(input=>input.onchange=async()=>{const file=input.files[0];if(!file)return;const key=input.dataset.upload;const fd=new FormData();fd.append('file',file);input.disabled=true;try{const r=await fetch('/api/upload',{method:'POST',headers:{'X-CSRF-Token':session.csrf},body:fd}),d=await r.json();if(!r.ok)throw Error(d.error||'Upload failed.');const target=root.querySelector(`[name="${key}"]`);target.value=d.url;root.querySelector(`[data-image-preview="${key}"]`).src=d.url;dirty=true;toast('Image uploaded and optimised to WebP. Save to apply it.')}catch(err){toast(err.message,true)}finally{input.disabled=false;input.value=''}});root.querySelectorAll('[data-image-preview]').forEach(img=>{const field=root.querySelector(`[name="${img.dataset.imagePreview}"]`);field?.addEventListener('change',()=>{if(/^\/(assets|uploads)\/[a-zA-Z0-9/_.-]+$/.test(field.value))img.src=field.value})})}
function bookingTable(items){if(!items.length)return `<div class="table-wrap">${empty('The next adventure starts here.','Paid bookings appear only after Stripe verifies successful payment. Unpaid and cancelled checkouts stay out of this list.')}</div>`;return `<div class="table-wrap"><table><thead><tr><th>Guest & experience</th><th>Tour date</th><th>Payment</th><th>Tour status</th><th>Action</th></tr></thead><tbody>${items.map(b=>`<tr><td><strong>${e(b.name)}</strong><small style="display:block;margin-top:5px">${e(b.reference)} · ${e(b.tourTitle)}</small></td><td>${e(b.date)}</td><td><strong>${money(b.total)}</strong><div style="margin-top:5px">${badge('Paid','green')} ${b.mode==='test'?badge('Test','orange'):''}</div></td><td>${badge(b.status,b.status==='confirmed'?'green':b.status==='cancelled'?'red':'orange')}</td><td>${btn('Review',`data-booking="${e(b.id)}"`,'secondary small')}</td></tr>`).join('')}</tbody></table></div>`}
function bookings(){const items=data.bookings.filter(b=>trash?!!b.deletedAt:!b.deletedAt).filter(b=>(!search||[b.name,b.reference,b.tourTitle,b.email].join(' ').toLowerCase().includes(search.toLowerCase()))&&(filter==='all'||b.status===filter||b.mode===filter)).sort((a,b)=>b.paidAt.localeCompare(a.paidAt));shell(head('Paid bookings','Payment and tour confirmation are separate. Confirm guest arrangements after reviewing the paid booking.',btn(trash?'Active bookings':'Show Trash','data-booking-trash')+btn('Refresh','data-refresh'))+`<div class="filters"><input id="booking-search" type="search" placeholder="Guest, reference or experience…" aria-label="Search bookings" value="${e(search)}"><select id="booking-filter" aria-label="Filter bookings">${[['all','All paid bookings'],['pending','Awaiting confirmation'],['confirmed','Confirmed'],['cancelled','Cancelled'],['test','Test payments'],['live','Live payments']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select><span class="count-label">${items.length} bookings${trash?' in Trash':''}</span></div>${bookingTable(items)}`);root.querySelector('[data-booking-trash]').onclick=()=>{trash=!trash;bookings()};const f=root.querySelector('#booking-search');f.oninput=()=>{const pos=f.selectionStart;search=f.value;bookings();const n=root.querySelector('#booking-search');n.focus();n.setSelectionRange(pos,pos)};root.querySelector('#booking-filter').onchange=ev=>{filter=ev.target.value;bookings()}}
function booking(id){const b=data.bookings.find(b=>b.id===id);if(!b)return;const rows=[['Reference',b.reference],['Experience',b.tourTitle],['Guest',b.name],['Email',b.email],['Phone',b.phone],['Tour date',b.date],['Adults / children',b.adults+' / '+b.children],['Units / hours',b.units],['Pickup',b.pickup||'Not specified'],['Notes',b.notes||'None'],['Paid at',new Date(b.paidAt).toLocaleString()],['Stripe payment',b.paymentIntent],['Stripe session',b.sessionId],['Customer receipt',b.customerReceiptSent?'SMTP accepted':'Not sent / email not configured']];shell(head('Booking '+b.reference,b.tourTitle,btn('← Back to bookings','data-back'))+`<div class="booking-detail"><div class="panel"><h2>Guest & travel details</h2>${(b.items||[]).map(item=>`<div class="notice"><h3>${e(item.tourTitle)}</h3><p>${e(item.date)} · ${item.adults+item.children} guests · ${money(item.total)}</p>${(item.addons||[]).map(a=>`<p>${e(a.title)} × ${a.quantity} · ${money(a.amount)}</p>`).join('')}</div>`).join('')}<dl class="detail-list">${rows.map(([k,v])=>`<dt>${k}</dt><dd>${e(v)}</dd>`).join('')}</dl></div><div><div class="panel"><div class="panel-head"><h2>Payment received</h2>${badge(b.mode==='test'?'Test payment':'Live payment',b.mode==='test'?'orange':'green')}</div><h1>${money(b.total)}</h1><p class="hint">${e(b.currency?.toUpperCase())} · Paid through Stripe</p>${(b.addons||[]).length?`<h3>Selected extras</h3>${b.addons.map(a=>`<p class="hint">${e(a.title)} · ${a.quantity} · ${money(a.amount)}</p>`).join('')}`:''}<hr><form id="booking-status">${select('Tour arrangements','status',b.status,[['pending','Awaiting tour confirmation'],['confirmed','Confirmed'],['cancelled','Cancelled']])}<p class="hint">Confirmation and cancellation emails send through the SMTP mailbox configured in Email delivery. Cancelling does not automatically refund a payment.</p><button class="button" type="submit">Update status</button></form><div class="form-error" role="status"></div></div><div class="danger-zone"><h3>${b.deletedAt?'Restore booking':'Move booking to Trash'}</h3><p class="hint">${b.deletedAt?'Restore this paid booking to your active bookings list.':'Hide this booking from your active list. Its payment record remains in Stripe. You can restore it from Trash.'}</p>${btn(b.deletedAt?'Restore booking':'Move to Trash','data-booking-remove',b.deletedAt?'secondary':'danger')}</div></div></div>`);root.querySelector('#booking-status').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{const d=await api('booking-status',{id,status:ev.target.elements.status.value});await reload();booking(id);toast(d.emailSent?'Status updated. Email accepted by SMTP.':d.mailConfigured?'Status saved. Email failed; save the same status to retry.':'Status saved. Configure SMTP to send guest notifications.',!d.emailSent)}catch(err){toast(err.message,true);button.disabled=false}};root.querySelector('[data-booking-remove]').onclick=async()=>{if(!b.deletedAt&&!confirm('Move this booking to Trash? This does not cancel or refund its Stripe payment.'))return;try{await api('booking-status',{id,action:b.deletedAt?'restore':'delete'});await reload();bookings();toast(b.deletedAt?'Booking restored.':'Booking moved to Trash.')}catch(err){toast(err.message,true)}}}
function inquiries(){const items=data.inquiries.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt));shell(head('Travel enquiries','Quote requests and general messages. These are separate from paid tour bookings.',btn('Refresh','data-refresh'))+`${items.length?items.map(i=>`<article class="panel"><div class="panel-head"><div><h2>${e(i.subject)}</h2><small>${e(i.createdAt.slice(0,10))}</small></div>${badge(i.emailSent?'Email accepted':'Saved to dashboard',i.emailSent?'green':'orange')}</div><p><strong>${e(i.name)}</strong> · <a class="help-link" href="mailto:${e(i.email)}">${e(i.email)}</a> · ${e(i.phone||'')}</p><p style="white-space:pre-line">${e(i.message)}</p></article>`).join(''):empty('A conversation can lead anywhere.','Contact and quote messages will appear here, even when email delivery is not configured.')}`)}
function settings(){const s=data.settings;shell(head('A brand with a point of view.','Keep your logo, business contacts and homepage introduction up to date.')+`<form id="settings-form" class="settings-grid"><div class="panel"><h2>Business details</h2><div class="two">${input('Business name','name',s.name,'text','','required')}${input('Tagline','tagline',s.tagline)}</div><div class="two">${input('Public email','email',s.email,'email','','required')}${input('Booking notifications sent to','bookingEmail',s.bookingEmail,'email','','required')}</div><div class="three">${input('Main phone','phone',s.phone,'tel')}${input('Second phone','phone2',s.phone2,'tel')}${input('Landline','landline',s.landline,'tel')}</div>${area('Office address','address',s.address,3)}${input('WhatsApp number','whatsapp',s.whatsapp,'tel','Include the country code. No spaces are needed.')}</div><div class="panel"><h2>Original logo & brand assets</h2>${imageFields(s,'logo','Website & dashboard logo')}<p class="hint">Use your original logo. The same image appears in the header, footer and dashboard. The favicon is already derived from your logo.</p></div><div class="panel"><h2>Homepage first impression</h2><div class="two">${input('Headline, first line','heroTitle',s.heroTitle)}${input('Headline, accent line','heroAccent',s.heroAccent)}</div>${area('Hero introduction','heroSummary',s.heroSummary,3)}${imageFields(s,'heroImage','Hero photograph')}</div><div class="panel"><h2>Social links</h2>${input('Facebook','facebook',s.facebook,'url')}${input('Instagram','instagram',s.instagram,'url')}${input('Threads','threads',s.threads,'url')}</div><div class="save-bar"><button class="button" type="submit">Save brand & contact</button></div></form>`);bindUploads();const form=root.querySelector('#settings-form');form.addEventListener('input',contentDirty);form.addEventListener('change',contentDirty);form.onsubmit=async ev=>{ev.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;try{await api('settings',Object.fromEntries(new FormData(form)));await reload();dirty=false;settings();toast('Your brand and contact details are updated.')}catch(err){toast(err.message,true);b.disabled=false}}}
function tracking(){const s=data.tracking||{};shell(head('Tracking & verification','Connect your marketing tools and verify website ownership without editing code.')+`<form id="tracking-form" class="settings-grid"><section class="panel"><div class="panel-head"><h2>Google Tag Manager</h2>${badge(s.gtmEnabled?'Enabled':'Disabled',s.gtmEnabled?'green':'orange')}</div><p>Use your web container ID. The website adds both the head script and body fallback automatically.</p>${input('Container ID','gtmId',s.gtmId,'text','Example: GTM-ABC1234. Paste the ID only.','maxlength="24" placeholder="GTM-ABC1234" autocapitalize="characters" spellcheck="false"')}${check('Enable Google Tag Manager','gtmEnabled',s.gtmEnabled)}<p class="hint"><a href="https://tagmanager.google.com/" target="_blank" rel="noopener noreferrer">Open Google Tag Manager ↗</a>. Publish your container there after configuring its tags.</p></section><section class="panel"><div class="panel-head"><h2>Google site verification</h2>${badge(s.googleVerification?'Token saved':'Not configured',s.googleVerification?'green':'orange')}</div><p>In Google Search Console, choose the HTML tag verification method for the URL-prefix property https://desertskytourism.com/.</p>${input('Google verification token','googleVerification',s.googleVerification,'text','Paste only the value inside content="…" from the google-site-verification tag. Leave blank to remove it.','maxlength="258" spellcheck="false" autocomplete="off"')}<p class="hint">Saving adds the meta tag to public pages. Return to <a href="https://search.google.com/search-console" target="_blank" rel="noopener noreferrer">Google Search Console ↗</a> and click Verify. Domain properties use DNS verification instead.</p></section><section class="panel"><div class="panel-head"><h2>Meta Pixel</h2>${badge(s.metaEnabled?'Enabled':'Disabled',s.metaEnabled?'green':'orange')}</div><p>Add your Pixel ID to record page views on visitor-facing pages. No customer contact or booking form fields are passed by this integration.</p>${input('Meta Pixel ID','metaPixelId',s.metaPixelId,'text','Example: 123456789012345. Paste the numeric ID only.','maxlength="25" inputmode="numeric" pattern="[0-9]*" spellcheck="false"')}${check('Enable Meta Pixel','metaEnabled',s.metaEnabled)}<p class="hint">Find the ID in <a href="https://business.facebook.com/events_manager2/" target="_blank" rel="noopener noreferrer">Meta Events Manager ↗</a>. If this Pixel is already installed through GTM, keep this direct integration disabled to avoid counting page views twice.</p></section><section class="panel"><h2>Where these settings apply</h2><p>Tags are added to the public website, including tour, guide and booking pages. Dashboard and account pages are excluded. Leaving IDs empty keeps tracking off; disabling a tool keeps its saved ID for later.</p><p class="hint">These fields install the base tags. Campaigns, conversion events and consent rules are configured separately in your marketing tools.</p></section><div class="save-bar"><p id="tracking-error" role="alert" hidden></p><button class="button" type="submit">Save tracking settings</button></div></form>`);const form=root.querySelector('#tracking-form');form.oninput=contentDirty;form.onchange=contentDirty;form.onsubmit=async event=>{event.preventDefault();const v=Object.fromEntries(new FormData(form));v.gtmEnabled=form.elements.gtmEnabled.checked;v.metaEnabled=form.elements.metaEnabled.checked;const b=form.querySelector('[type="submit"]'),error=form.querySelector('[role="alert"]');b.disabled=true;b.textContent='Saving…';error.hidden=true;try{const result=await api('tracking',v);data.tracking=result.tracking;dirty=false;tracking();toast('Tracking settings saved.');}catch(err){error.textContent=err.message;error.hidden=false;b.disabled=false;b.textContent='Save tracking settings';}};}

function payments(){const s=data.stripe;shell(head('Stripe, connected to your next adventure.','Guests pay in Stripe Checkout. Only verified successful payments create dashboard bookings.')+`<div class="settings-grid"><div class="panel"><div class="panel-head"><div class="stripe-title"><span>stripe</span><h2 style="margin:0">Secure tour payments</h2></div><div class="status-stack">${badge(s.enabled?'Checkout enabled':'Checkout disabled',s.enabled?'green':'orange')}${badge(s.mode==='live'?'Live mode':'Test mode',s.mode==='live'?'green':'orange')}</div></div><p class="muted">${s.connected?'Saved API key ends in '+e(s.keySuffix)+'. Secrets stay on the server and are never shown again.':'Connect your Stripe account with an API key. You do not need to share your Stripe account password.'}</p><form id="stripe-form">${input('Stripe secret or restricted API key','secret','','password',s.connected?'Leave blank to keep the saved key.':'Start with a test key. Use a live key only when you are ready.','autocomplete="new-password" spellcheck="false"')}${input('Webhook signing secret (optional if created automatically)','webhook','','password',s.webhookConfigured?'A signing secret is already saved. Leave blank to keep it.':'Starts with whsec_. Enter it if you created the endpoint yourself.','autocomplete="new-password" spellcheck="false"')}${check('Create the webhook automatically','autoWebhook',!s.webhookConfigured,'Requires webhook endpoint write access on the API key. Existing signing secrets are kept.')}${check('Enable paid checkout','enabled',s.enabled,'Enabled only after the API key and webhook signing secret are configured.')}<div class="page-actions" style="justify-content:flex-start"><button class="button" type="submit">${s.connected?'Update Stripe connection':'Connect Stripe'}</button>${s.connected?btn('Disconnect','data-disconnect','danger'):''}</div><div class="form-error" role="status"></div></form></div><div class="panel"><h2>A simple setup, on your terms.</h2><ol class="setup-steps"><li>Open your <a href="https://dashboard.stripe.com/test/apikeys" target="_blank" rel="noopener noreferrer">Stripe test API keys</a>. Use a restricted key where possible. It needs balance read, Checkout Sessions read/write, and webhook endpoints write if automatic setup is selected.</li><li>Paste the key in the private field above. Turn on automatic webhook setup, enable checkout and connect. The website validates the key and creates its endpoint.</li><li>If you prefer manual setup, create an endpoint in Stripe with this URL:<code class="code-copy">${e(s.endpoint)}</code>Enable <code>checkout.session.completed</code>, <code>checkout.session.async_payment_succeeded</code> and <code>checkout.session.async_payment_failed</code>. Paste that endpoint’s signing secret above.</li><li>Use test checkout to verify a successful, cancelled and failed payment. Confirm that only a successful payment adds a booking.</li><li>When ready, add a live key and create or enter the matching live webhook secret. Complete a test payment before enabling live checkout.</li></ol><div class="notice blue">A guest’s redirect is not proof of payment. The server verifies the paid amount, currency, Checkout Session and payment mode. Signed webhooks also record payments when a guest closes the browser.</div><p class="security-note">Payments are collected in AED. Payment completion and tour confirmation are separate. Refunds are handled through Stripe; cancelling a tour status does not automatically refund the card. Stripe fees and available payment methods depend on your account.</p></div></div>`);const form=root.querySelector('#stripe-form');form.onsubmit=async ev=>{ev.preventDefault();const v=Object.fromEntries(new FormData(form));v.enabled=!!v.enabled;v.autoWebhook=!!v.autoWebhook;const b=form.querySelector('[type=submit]');b.disabled=true;try{const d=await api('stripe',v);data.stripe=d.stripe;payments();toast(d.stripe.enabled?'Stripe connected. Paid checkout is enabled.':'Connection saved. Checkout is currently disabled.')}catch(err){form.querySelector('.form-error').textContent=err.message;toast(err.message,true);b.disabled=false}};root.querySelector('[data-disconnect]')?.addEventListener('click',async()=>{if(!confirm('Disable checkout and remove the saved Stripe credentials from this website? Existing payments remain in Stripe.'))return;try{const d=await api('stripe',{disconnect:true});data.stripe=d.stripe;payments();toast('Stripe disconnected. Checkout is disabled.')}catch(err){toast(err.message,true)}})}
function email(){const c=data.mail;shell(head('Keep guests in the loop.','Connect an authenticated mailbox for receipts, booking notifications and status updates.')+`<div class="settings-grid"><div class="notice blue">Bookings and enquiries remain saved even if email delivery fails. SMTP acceptance means the provider accepted the message; inbox placement still depends on the recipient and your domain’s email authentication.</div><form id="email-form" class="panel"><div class="panel-head"><h2>Your sending mailbox</h2>${badge(c.configured?'Mailbox saved':'Not configured',c.configured?'green':'orange')}</div><div class="two">${select('SMTP provider','host',c.host,[['smtp.hostinger.com','Hostinger Email'],['smtp.titan.email','Titan Email'],['smtp.gmail.com','Gmail (app password)'],['smtp.office365.com','Microsoft 365']])}${select('SMTP port','port',c.port,[[465,'465 — SSL'],[587,'587 — STARTTLS']])}</div>${input('Mailbox email address','username',c.username,'email','This address is used as the message sender.','required autocomplete="off"')}${input('Mailbox / app password','password','','password',c.configured?'Leave blank to keep the saved password.':'Use the mailbox password or provider app password, not your hosting password.','autocomplete="new-password"')}<p class="security-note">Secrets are saved in private server storage. The dashboard never returns the saved password. A connection test sends one email to your administrator address: ${e(session.email)}.</p><button class="button" type="submit">Save and send test email</button><div class="form-error" role="status"></div></form><div class="panel"><h2>When messages send</h2><ul class="setup-steps"><li>After successful payment: booking receipt to the guest and notification to ${e(data.settings.bookingEmail)}.</li><li>After an admin confirms or cancels a booking: a status email to that guest.</li><li>After a general enquiry: a message to your business notifications inbox.</li></ul><p class="hint">If a status notification fails, save that same status again after fixing SMTP to retry. Configure SPF, DKIM and DMARC in your email provider for reliable delivery.</p></div></div>`);const form=root.querySelector('#email-form');form.onsubmit=async ev=>{ev.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const d=await api('mail',Object.fromEntries(new FormData(form)));await reload();email();toast(d.message,!d.ok)}catch(err){toast(err.message,true);b.disabled=false}}}
function security(){shell(head('Your workspace, protected.','Update your password and keep your administrator access private.')+`<div class="settings-grid"><form id="password-form" class="panel"><h2>Change your password</h2><p class="muted">Signed in as ${e(session.email)}</p>${input('Current password','currentPassword','','password','','required autocomplete="current-password"')}${input('New password','password','','password','Use at least 12 characters.','required minlength="12" maxlength="200" autocomplete="new-password"')}${input('Repeat new password','repeatPassword','','password','','required minlength="12" autocomplete="new-password"')}<button class="button" type="submit">Update password</button><div class="form-error" role="status"></div></form><div class="panel"><h2>Built for private access</h2><p class="security-note">Administrator passwords are hashed. Sessions expire after 8 hours and use secure cookies. Updating your password invalidates other sessions. Stripe and SMTP secrets stay outside the public website folder. No private configuration is included in the website HTML.</p></div></div>`);const form=root.querySelector('#password-form');form.onsubmit=async ev=>{ev.preventDefault();const v=Object.fromEntries(new FormData(form));if(v.password!==v.repeatPassword){toast('The new passwords do not match.',true);return}const b=form.querySelector('button');b.disabled=true;try{await api('password',v);form.reset();toast('Password updated. Other sessions have been signed out.')}catch(err){toast(err.message,true)}finally{b.disabled=false}}}
function login(){root.innerHTML=`<div class="login-page"><section class="login-visual"><div><span>Desert Sky Studio</span><h1>Good days.<br>Great possibilities.</h1><p>A place to shape the next adventure, one experience at a time.</p></div></section><main class="login-content"><div class="login-box"><a href="/"><img class="login-logo" src="/assets/logo.webp" alt="Desert Sky Tourism original logo"></a><h2>Welcome to your studio.</h2><p>Sign in to manage your experiences, content and paid bookings.</p><form id="login-form">${input('Email address','email','','email','','required autocomplete="username"')}${input('Password','password','','password','','required autocomplete="current-password"')}<button class="button" type="submit">Sign in →</button><div class="form-error" role="alert"></div></form><div class="login-foot"><a href="/">← Back to Desert Sky Tourism</a></div></div></main></div>`;const form=root.querySelector('#login-form');form.onsubmit=async ev=>{ev.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const d=await api('login',Object.fromEntries(new FormData(form)));session.csrf=d.csrf;session=await api('session');await reload();render()}catch(err){form.querySelector('.form-error').textContent=err.message;b.disabled=false}}}
async function deleteUser(email,button){
 if(!confirm('Permanently delete '+email+'? This removes their account and sign-in access. Existing booking records will be kept. This cannot be undone.'))return;
 const label=button.textContent;button.disabled=true;button.textContent='Deleting…';
 try{await api('users',{action:'delete',email,confirmationEmail:email});dirty=false;await users();toast('User deleted. Existing booking records were kept.');}
 catch(err){toast(err.message,true);button.disabled=false;button.textContent=label;}
}
function userDate(value){if(!value)return 'Not recorded';const date=new Date(value);return Number.isNaN(date.getTime())?'Not recorded':date.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});}
async function users(){
 shell(head('Users','Manage administrator access and customer accounts.')+'<div class="panel" role="status">Loading users…</div>');
 try{const result=await api('users');if(tab!=='users')return;const all=result.users;
 shell(head('Users','Administrators manage the website. Subscribers can sign in to view their own bookings.',btn('Refresh','data-users-refresh')+btn('+ Add user','data-user-new',''))+`<div class="filters"><input id="user-search" type="search" aria-label="Search users" placeholder="Search name, email or phone…"><select id="user-role" aria-label="Filter user role"><option value="all">All roles</option><option value="administrator">Administrators</option><option value="subscriber">Subscribers</option></select><select id="user-status" aria-label="Filter account status"><option value="all">All statuses</option><option value="active">Active</option><option value="disabled">Disabled</option></select><span class="count-label" id="user-count"></span></div><div id="user-results"></div>`);
 const draw=()=>{const q=root.querySelector('#user-search').value.toLowerCase().trim(),role=root.querySelector('#user-role').value,status=root.querySelector('#user-status').value;const selected=all.filter(u=>(!q||[u.name,u.email,u.phone].join(' ').toLowerCase().includes(q))&&(role==='all'||u.role===role)&&(status==='all'||(u.disabled?'disabled':'active')===status));root.querySelector('#user-count').textContent=selected.length+(selected.length===1?' user':' users');root.querySelector('#user-results').innerHTML=selected.length?`<div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Last sign-in</th><th>Bookings</th><th>Actions</th></tr></thead><tbody>${selected.map(u=>`<tr><td><div class="table-title"><div><strong>${e(u.name||u.email)}</strong><small>${e(u.email)}${u.email===session.email?' · You':''}</small>${u.phone?`<small>${e(u.phone)}</small>`:''}</div></div></td><td>${badge(u.role==='administrator'?'Administrator':'Subscriber',u.role==='administrator'?'orange':'')}</td><td>${badge(u.disabled?'Disabled':'Active',u.disabled?'red':'green')}</td><td>${e(userDate(u.lastLogin))}</td><td>${u.bookingCount}</td><td><div class="table-actions">${btn('View / Edit',`data-user="${e(u.email)}"`,'secondary small')}${u.email===session.email?btn('Delete','','danger small','disabled title="Your own administrator account is protected"'):btn('Delete',`data-user-delete="${e(u.email)}"`,'danger small')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No matching users','Customer accounts appear here automatically when someone signs up.');root.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>userEditor(b.dataset.user));root.querySelectorAll('[data-user-delete]').forEach(b=>b.onclick=()=>deleteUser(b.dataset.userDelete,b));};
 root.querySelector('#user-search').oninput=draw;root.querySelector('#user-role').onchange=draw;root.querySelector('#user-status').onchange=draw;root.querySelector('[data-user-new]').onclick=()=>userEditor();root.querySelector('[data-users-refresh]').onclick=users;draw();
 }catch(err){toast(err.message,true);}
}
async function userEditor(email=''){
 try{const result=email?await api('users?email='+encodeURIComponent(email)):{user:{name:'',email:'',phone:'',role:'subscriber',disabled:false},bookings:[]};if(tab!=='users')return;const u=result.user,self=u.email===session.email;
 const history=result.bookings.filter(b=>data.bookings.some(v=>v.id===b.id&&!v.deletedAt));
 const meta=email?`<section class="panel"><h2>Account details</h2><dl class="user-meta"><div><dt>Registered</dt><dd>${e(userDate(u.createdAt))}</dd></div><div><dt>Last sign-in</dt><dd>${e(userDate(u.lastLogin))}</dd></div><div><dt>Email verification</dt><dd>${u.customerId?(u.verified?'Verified':'Not verified'):'Administrator account'}</dd></div><div><dt>Customer ID</dt><dd>${e(u.customerId||'No customer profile')}</dd></div></dl></section>`:'';
 const bookings=email?`<section class="panel"><h2>Customer bookings</h2><p>Paid bookings linked to this customer account. Earlier guest bookings are not linked by email alone.</p>${history.length?`<div class="table-wrap"><table><thead><tr><th>Reference / Experience</th><th>Tour date</th><th>Status</th><th>Total</th><th>Details</th></tr></thead><tbody>${history.map(b=>`<tr><td><strong>${e(b.reference)}</strong><br>${e(b.tourTitle||(b.items||[]).map(i=>i.tourTitle).join(', '))}</td><td>${e(b.date||'See booking')}</td><td>${badge(b.status||'pending')}</td><td>${money(b.total)}</td><td>${btn('Review',`data-booking="${e(b.id)}"`,'secondary small')}</td></tr>`).join('')}</tbody></table></div>`:empty('No linked bookings','Successful payments for this account will appear here.')}</section>`:'';
 shell(head(email?'User profile':'Add user',email?'View account details, access and booking history.':'Create a customer account or grant full administrator access.',btn('← All users','data-back')+(email&&!self?btn('Delete user','data-profile-delete','danger'):''))+`<form id="user-form"><section class="panel"><h2>${email?'Profile & access':'New account'}</h2><div class="two">${input('Full name','name',u.name,'text','','required minlength="2" maxlength="150" autocomplete="name"')}${input('Email address','email',u.email,'email',email?'Email is the account identifier and cannot be changed here.':'Use an email address owned by this user.',`required maxlength="254" autocomplete="email" ${email?'readonly':''}`)}${input('Phone number','phone',u.phone,'tel','','maxlength="50" autocomplete="tel"')}${select('Account role','role',u.role,[['subscriber','Subscriber — customer account'],['administrator','Administrator — full dashboard access']])}${select('Account status','status',u.disabled?'disabled':'active',[['active','Active'],['disabled','Disabled — sign-in blocked']])}${self?'':input(email?'Set a new password (optional)':'Initial password','password','','password',email?'Leave empty to keep the current password.':'At least 12 characters. Share it with the user privately; no invitation email is sent.',`minlength="12" maxlength="200" autocomplete="new-password" ${email?'':'required'}`)}</div><p class="hint">Administrators have full access to content, users, bookings and integration settings. Subscribers can access only their own customer account.</p>${self?'<p class="notice">Your administrator role and active status are protected. Change your own password in Account security.</p>':''}<p id="user-form-error" role="alert" class="user-form-error" hidden></p><button class="button" type="submit">${email?'Save changes':'Create user'}</button></section></form>${meta}${bookings}`);
 if(self){root.querySelector('[name="role"]').disabled=true;root.querySelector('[name="status"]').disabled=true;}
 if(email&&!self)root.querySelector('[data-profile-delete]').onclick=event=>deleteUser(email,event.currentTarget);
 const form=root.querySelector('#user-form');form.oninput=contentDirty;form.onchange=contentDirty;
 root.querySelectorAll('[data-booking]').forEach(b=>b.onclick=()=>{if(!dirty||confirm('Leave without saving changes?')){dirty=false;booking(b.dataset.booking);}});
 form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form));if(self){values.role=u.role;values.status='active';}if(values.role==='administrator'&&(!email||u.role!=='administrator')&&!confirm('Give '+values.email+' full administrator access to this website?'))return;
 const button=form.querySelector('[type="submit"]'),error=form.querySelector('[role="alert"]');button.disabled=true;button.textContent='Saving…';error.hidden=true;
 try{await api('users',{...values,action:email?'update':'create',disabled:values.status==='disabled'});dirty=false;await userEditor(values.email);toast(email?'User updated.':'User created.');}catch(err){error.textContent=err.message;error.hidden=false;error.focus();button.disabled=false;button.textContent=email?'Save changes':'Create user';}
 };
 }catch(err){toast(err.message,true);}
}

function studioIcon(name){const p={tracking:'<path d="M4 20V10m6 10V4m6 16v-7m5 7H1"/>',users:'<circle cx="9" cy="8" r="4"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M17 4a4 4 0 0 1 0 8m2 3a6 6 0 0 1 3 5"/>',overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',tours:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/>',locations:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',posts:'<path d="M4 3h11l5 5v13H4Z"/><path d="M14 3v6h6M8 13h8M8 17h6"/>',pages:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M9 9v11"/>',bookings:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 5 3 3 5-5"/>',inquiries:'<path d="M21 11a8 8 0 0 1-8 8H7l-5 3V11a9 9 0 0 1 19 0Z"/><path d="M7 9h9M7 13h6"/>',reviews:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor"/><circle cx="15" cy="17" r="3" fill="currentColor"/>',payments:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h3"/>',email:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',security:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>'};return `<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.tours}</svg>`}
function reviews(){
 const items=(data.reviews||[]).filter(r=>trash?!!r.deletedAt:!r.deletedAt);
 const cards=items.map(r=>{const actions=trash?btn('Restore',`data-restore="${e(r.id)}"`,'secondary small'):btn('Edit review',`data-edit="${e(r.id)}"`,'secondary small')+btn('Move to Trash',`data-delete="${e(r.id)}"`,'danger small');return `<article class="panel review-admin-card"><div class="panel-head"><div><span class="admin-review-stars" aria-label="${r.rating} out of 5">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span><h2>${e(r.title)}</h2></div>${badge(r.isSample?'Sample review':r.status,r.isSample?'orange':r.status==='published'?'green':'')}</div><p>${r.quote?`“${e(r.quote)}”`:'Rating only — no written review.'}</p><div class="admin-review-author"><span>${e(r.author.slice(0,1))}</span><div><strong>${e(r.author)}</strong><small>${e(r.location)}</small></div></div><div class="page-actions">${actions}</div></article>`}).join('');
 const body=items.length?`<div class="review-admin-grid">${cards}</div>`:empty(trash?'No reviews in Trash.':'Your next great story starts here.','Add guest feedback to display it in the homepage review carousel.');
 shell(head('Stories worth sharing.','Manage genuine guest feedback and clearly marked sample reviews. Edit, publish or restore them whenever you need.',btn(trash?'Active reviews':'Show Trash','data-review-trash')+btn('+ Add a review','data-new',''))+'<div class="notice blue">Sample reviews are clearly labelled on the website. Replace or delete them before launching the website for real guests.</div>'+body);
 root.querySelector('[data-review-trash]').onclick=()=>{trash=!trash;reviews()};
}
function editReview(id){const r=(data.reviews||[]).find(r=>r.id===id)||{id:'',title:'',author:'',quote:'',rating:5,location:'',status:'draft',publishedAt:new Date().toISOString().slice(0,10),isSample:false,source:''};editing=r;shell(head(r.id?'Edit a guest story.':'A new story, worth sharing.','Keep feedback authentic. Mark placeholders as sample reviews.',btn('← Back to reviews','data-back'))+`<form id="review-form"><div class="edit-grid"><div class="panel"><h2>The guest’s words</h2>${input('Review headline','title',r.title,'text','','required')}${area('Review text','quote',r.quote,7,'Use the guest’s own words for genuine feedback.') }<div class="two">${input('Guest name','author',r.author,'text','','required')}${input('Location / experience','location',r.location)}</div><div class="two">${select('Rating','rating',r.rating,[[5,'5 stars'],[4,'4 stars'],[3,'3 stars'],[2,'2 stars'],[1,'1 star']])}${input('Date','publishedAt',r.publishedAt?.slice(0,10),'date')}</div>${check('Rating only — no written feedback','ratingOnly',r.ratingOnly)}${input('Review platform','sourcePlatform',r.sourcePlatform||'')}${input('Original review date label','sourceDate',r.sourceDate||'','text','Keep the original relative date for imported Google reviews.')}<input type="hidden" name="sourceReviewId" value="${e(r.sourceReviewId||'')}">${check('This text is an excerpt','isExcerpt',r.isExcerpt)}${input('Original review link (optional)','source',r.source,'url','Use an https:// link to the original Google or other review.')}</div><aside class="edit-aside"><div class="panel"><h3>Publication</h3>${select('Status','status',r.status,[['draft','Draft'],['published','Published']])}${check('This is a sample review','isSample',r.isSample,'Shows a visible Sample review label on the website. Keep this enabled for dummy content.')}<p class="hint">Published reviews appear in the homepage carousel. Draft reviews remain private.</p></div></aside></div><div class="save-bar"><button class="button" type="submit">Save review</button></div><div class="form-error" role="alert"></div></form>`);const form=root.querySelector('#review-form');form.addEventListener('input',contentDirty);form.addEventListener('change',contentDirty);form.onsubmit=async ev=>{ev.preventDefault();const values=Object.fromEntries(new FormData(form));values.id=r.id;values.isSample=!!values.isSample;values.ratingOnly=!!values.ratingOnly;values.isExcerpt=!!values.isExcerpt;values.rating=Number(values.rating);const b=form.querySelector('[type=submit]');b.disabled=true;try{const result=await api('content',{kind:'reviews',value:values});await reload();dirty=false;editReview(result.value.id);toast('Review saved. Your carousel is updated.')}catch(err){form.querySelector('.form-error').textContent=err.message;b.disabled=false;toast(err.message,true)}};dirty=false}
function bindGalleryUploads(){const input=root.querySelector('[data-gallery-upload]');if(!input)return;input.onchange=async()=>{const files=[...input.files].slice(0,8);input.disabled=true;try{for(const file of files){const f=new FormData();f.append('file',file);const r=await fetch('/api/upload',{method:'POST',headers:{'X-CSRF-Token':session.csrf},body:f}),v=await r.json();if(!r.ok)throw Error(v.error||'Photo upload failed.');const field=root.querySelector('[name=galleryImages]');field.value=[...new Set([...field.value.split('\n').filter(Boolean),v.url])].join('\n');dirty=true}toast('Gallery photographs uploaded. Save the experience to apply them.')}catch(err){toast(err.message,true)}finally{input.disabled=false;input.value=''}}}
function openStudioSearch(){let d=document.querySelector('#studio-search-dialog');if(d)d.remove();d=document.createElement('dialog');d.id='studio-search-dialog';d.innerHTML=`<div class="studio-search-top">${studioIcon('search')}<input type="search" placeholder="Search experiences, guides, destinations…" aria-label="Search your workspace"><button type="button" aria-label="Close search">×</button></div><div class="studio-search-results"></div>`;document.body.append(d);const results=d.querySelector('.studio-search-results');const update=()=>{const query=d.querySelector('input').value.trim().toLowerCase();const found=[];for(const kind of ['tours','posts','pages','locations','reviews'])for(const item of data[kind]||[]){if(!item.deletedAt&&(!query||[item.title,item.author,item.slug].join(' ').toLowerCase().includes(query)))found.push({kind,item})}results.innerHTML=found.slice(0,12).map(({kind,item})=>`<button type="button" data-search-kind="${kind}" data-search-id="${e(item.id)}"><span>${studioIcon(kind)}</span><div><strong>${e(item.title)}</strong><small>${e(titles[kind])}</small></div>${studioIcon('arrow')}</button>`).join('')||'<p class="muted">No matching content. Try a different search.</p>';results.querySelectorAll('button').forEach(b=>b.onclick=()=>{if(dirty&&!confirm('Leave without saving your current changes?'))return;dirty=false;tab=b.dataset.searchKind;location.hash=tab;d.close();d.remove();edit(b.dataset.searchId)})};d.querySelector('input').oninput=update;d.querySelector('button').onclick=()=>{d.close();d.remove()};update();d.showModal();d.querySelector('input').focus()}

window.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'&&session.admin){event.preventDefault();openStudioSearch()}});window.addEventListener('beforeunload',ev=>{if(dirty){ev.preventDefault();ev.returnValue=''}});async function init(){try{session=await api('session');if(!session.admin){login();return}await reload();const hash=location.hash.slice(1);tab=Object.hasOwn(titles,hash)?hash:'overview';render()}catch(err){root.innerHTML=empty('We couldn’t load your workspace.','Please refresh the page to try again.');toast(err.message,true)}}init();})();
